-			return fmt.Errorf("invalid session ID for logging: %w", err)
+			return ctx, fmt.Errorf("invalid session ID for logging: %w", err)
 		}
 	}

@@ -120,7 +128,7 @@ func Init(ctx context.Context, sessionID string) error {
