     1	// Package logging provides structured logging for the Entire CLI using slog.
     2	//
     3	// Usage:
     4	//
     5	//	// Initialize logger for a session (typically at the cobra entry point);
     6	//	// the returned context carries the logger for downstream injection.
     7	//	ctx, err := logging.Init(ctx, sessionID)
     8	//	if err != nil {
     9	//	    // handle error
    10	//	}
    11	//	defer logging.Close()
    12	//
    13	//	// Add context values
    14	//	ctx = logging.WithComponent(ctx, "hooks")
    15	//	ctx = logging.WithAgent(ctx, agentName)
    16	//
    17	//	// Log with context - component/agent extracted automatically
    18	//	logging.Info(ctx, "hook invoked",
    19	//	    slog.String("hook", hookName),
    20	//	    slog.String("branch", branch),
    21	//	)
    22	package logging
    23	
    24	import (
    25		"bufio"
    26		"context"
    27		"fmt"
    28		"io"
    29		"log/slog"
    30		"os"
    31		"path/filepath"
    32		"strings"
    33		"sync"
    34	
    35		"github.com/entireio/cli/cmd/entire/cli/paths"
    36		"github.com/entireio/cli/cmd/entire/cli/validation"
    37	)
    38	
    39	// LogLevelEnvVar is the environment variable that controls log level.
    40	const LogLevelEnvVar = "ENTIRE_LOG_LEVEL"
    41	
    42	// LogsDir is the directory where log files are stored (relative to repo root).
    43	const LogsDir = ".entire/logs"
    44	
    45	var (
    46		// logger is the package-level logger instance
    47		logger *slog.Logger
    48	
    49		// logFile holds the current log file handle for cleanup
    50		logFile *os.File
    51	
    52		// logBufWriter wraps logFile with buffered I/O for performance
    53		logBufWriter *bufio.Writer
    54	
    55		// currentSessionID stores the session ID from Init() to include in all logs
    56		currentSessionID string
    57	
    58		// mu protects logger, logFile, logBufWriter, and currentSessionID
    59		mu sync.RWMutex
    60	
    61		// logLevelGetter is an optional callback to get log level from settings.
    62		// Set by SetLogLevelGetter before Init is called.
    63		logLevelGetter func() string
    64	)
    65	
    66	// SetLogLevelGetter sets a callback function to get the log level from settings.
    67	// This allows the logging package to read settings without a circular dependency.
    68	// The callback is only used if ENTIRE_LOG_LEVEL env var is not set.
    69	func SetLogLevelGetter(getter func() string) {
    70		mu.Lock()
    71		defer mu.Unlock()
    72		logLevelGetter = getter
    73	}
    74	
    75	// Init initializes the logger for a session, writing JSON logs to
    76	// .entire/logs/entire.log.
    77	//
    78	// If sessionID is non-empty, it is stored as an slog attribute on every log line for filtering.
    79	// If the log file cannot be created, falls back to stderr.
    80	// Log level is controlled by ENTIRE_LOG_LEVEL environment variable.
    81	//
    82	// The returned context carries the initialized logger (see LoggerFromContext),
    83	// already stamped with session_id when one was given. Entry points pass it
    84	// down so downstream code — and packages that take an injected *slog.Logger,
    85	// like redact — never need to ask whether logging is ready. On error the
    86	// input context is returned unchanged.
    87	func Init(ctx context.Context, sessionID string) (context.Context, error) {
    88		// Validate session ID if provided (used only for the slog attribute, not the filename)
    89		if sessionID != "" {
    90			if err := validation.ValidateSessionID(sessionID); err != nil {
    91				return ctx, fmt.Errorf("invalid session ID for logging: %w", err)
    92			}
    93		}
    94	
    95		mu.Lock()
    96		defer mu.Unlock()
    97	
    98		// Close any existing log file (flush buffer first)
    99		if logBufWriter != nil {
   100			_ = logBufWriter.Flush()
   101			logBufWriter = nil
   102		}
   103		if logFile != nil {
   104			_ = logFile.Close()
   105			logFile = nil
   106		}
   107	
   108		// Get log level from environment first, then settings
   109		levelStr := os.Getenv(LogLevelEnvVar)
   110		if levelStr == "" && logLevelGetter != nil {
   111			levelStr = logLevelGetter()
   112		}
   113		level := parseLogLevel(levelStr)
   114	
   115		// Warn if invalid level was provided
   116		if levelStr != "" && !isValidLogLevel(levelStr) {
   117			fmt.Fprintf(os.Stderr, "[entire] Warning: invalid log level %q, defaulting to INFO\n", levelStr)
   118		}
   119	
   120		// Determine log file path
   121		repoRoot, err := paths.WorktreeRoot(ctx)
   122		if err != nil {
   123			// Fall back to current directory
   124			repoRoot = "."
   125		}
   126	
   127		logsPath := filepath.Join(repoRoot, LogsDir)
   128		if err := os.MkdirAll(logsPath, 0o750); err != nil {
   129			// Fall back to stderr
   130			logger = createLogger(os.Stderr, level)
   131			return contextWithInitLogger(ctx, logger, sessionID), nil
   132		}
   133	
   134		logFilePath := filepath.Join(logsPath, "entire.log")
   135		f, err := os.OpenFile(logFilePath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600) //nolint:gosec // fixed filename, not user-controlled
   136		if err != nil {
   137			// Fall back to stderr
   138			logger = createLogger(os.Stderr, level)
   139			return contextWithInitLogger(ctx, logger, sessionID), nil
   140		}
   141	
   142		logFile = f
   143		logBufWriter = bufio.NewWriterSize(f, 8192) // 8KB buffer for batched writes
   144		logger = createLogger(logBufWriter, level)
   145		currentSessionID = sessionID
   146	
   147		return contextWithInitLogger(ctx, logger, sessionID), nil
   148	}
   149	
   150	// contextWithInitLogger attaches the logger Init built to the context,
   151	// pre-stamped with session_id so direct consumers emit lines filterable the
   152	// same way as the package-level Debug/Info/Warn/Error functions.
   153	func contextWithInitLogger(ctx context.Context, l *slog.Logger, sessionID string) context.Context {
   154		if sessionID != "" {
   155			l = l.With(slog.String("session_id", sessionID))
   156		}
   157		return WithLogger(ctx, l)
   158	}
   159	
   160	// Close closes the log file if one is open.
   161	// Flushes any buffered data before closing.
   162	// Safe to call multiple times.
   163	func Close() {
   164		mu.Lock()
   165		defer mu.Unlock()
   166	
   167		if logBufWriter != nil {
   168			_ = logBufWriter.Flush()
   169			logBufWriter = nil
   170		}
   171		if logFile != nil {
   172			_ = logFile.Close()
   173			logFile = nil
   174		}
   175		currentSessionID = ""
   176	}
   177	
   178	// resetLogger resets the logger to nil (for testing).
   179	func resetLogger() {
   180		mu.Lock()
   181		defer mu.Unlock()
   182		logger = nil
   183		currentSessionID = ""
   184		if logBufWriter != nil {
   185			_ = logBufWriter.Flush()
   186			logBufWriter = nil
   187		}
   188		if logFile != nil {
   189			_ = logFile.Close()
   190			logFile = nil
   191		}
   192	}
   193	
   194	// createLogger creates a JSON logger writing to the given writer at the specified level.
   195	func createLogger(w io.Writer, level slog.Level) *slog.Logger {
   196		opts := &slog.HandlerOptions{
   197			Level: level,
   198		}
   199		handler := slog.NewJSONHandler(w, opts)
   200		return slog.New(handler)
   201	}
   202	
   203	// parseLogLevel parses a log level string to slog.Level.
   204	// Returns slog.LevelInfo for empty or invalid values.
   205	func parseLogLevel(s string) slog.Level {
   206		switch strings.ToUpper(strings.TrimSpace(s)) {
   207		case "DEBUG":
   208			return slog.LevelDebug
   209		case "INFO":
   210			return slog.LevelInfo
   211		case "WARN", "WARNING":
   212			return slog.LevelWarn
   213		case "ERROR":
   214			return slog.LevelError
   215		default:
   216			return slog.LevelInfo
   217		}
   218	}
   219	
   220	// isValidLogLevel checks if the given string is a valid log level.
   221	func isValidLogLevel(s string) bool {
   222		switch strings.ToUpper(strings.TrimSpace(s)) {
   223		case "DEBUG", "INFO", "WARN", "WARNING", "ERROR", "":
   224			return true
   225		default:
   226			return false
   227		}
   228	}
   229	
   230	// Debug logs at DEBUG level with context values automatically extracted.
   231	func Debug(ctx context.Context, msg string, attrs ...any) {
   232		log(ctx, slog.LevelDebug, msg, attrs...)
   233	}
   234	
   235	// Info logs at INFO level with context values automatically extracted.
   236	func Info(ctx context.Context, msg string, attrs ...any) {
   237		log(ctx, slog.LevelInfo, msg, attrs...)
   238	}
   239	
   240	// Warn logs at WARN level with context values automatically extracted.
   241	func Warn(ctx context.Context, msg string, attrs ...any) {
   242		log(ctx, slog.LevelWarn, msg, attrs...)
   243	}
   244	
   245	// Error logs at ERROR level with context values automatically extracted.
   246	func Error(ctx context.Context, msg string, attrs ...any) {
   247		log(ctx, slog.LevelError, msg, attrs...)
   248	}
   249	
   250	// log is the internal logging function that extracts context values and logs.
   251	//
   252	// The read lock is held across l.Log so Init/Close cannot close logBufWriter
   253	// mid-write; do not shrink the lock scope to a snapshot pattern.
   254	func log(ctx context.Context, level slog.Level, msg string, attrs ...any) {
   255		mu.RLock()
   256		defer mu.RUnlock()
   257	
   258		l := logger
   259		if l == nil {
   260			l = slog.Default()
   261		}
   262		globalSessionID := currentSessionID
   263	
   264		// Build attributes slice with session ID first (if set)
   265		var allAttrs []any
   266	
   267		// Add session ID from Init() if set (always first for consistency)
   268		if globalSessionID != "" {
   269			allAttrs = append(allAttrs, slog.String("session_id", globalSessionID))
   270		}
   271	
   272		// Extract context values
   273		contextAttrs := attrsFromContext(ctx)
   274		for _, a := range contextAttrs {
   275			allAttrs = append(allAttrs, a)
   276		}
   277	
   278		// Add caller-provided attributes
   279		allAttrs = append(allAttrs, attrs...)
   280	
   281		// Pass nil context to slog as we've already extracted context values as attributes.
   282		// slog handlers are expected to handle nil context gracefully.
   283		l.Log(nil, level, msg, allAttrs...) //nolint:staticcheck // nil context is intentional - we extract values as attributes
   284	}
   285	
   286	// attrsFromContext extracts logging attributes from a context.
   287	func attrsFromContext(ctx context.Context) []slog.Attr {
   288		if ctx == nil {
   289			return nil
   290		}
   291	
   292		var attrs []slog.Attr
   293	
   294		if v := ctx.Value(componentKey); v != nil {
   295			if s, ok := v.(string); ok && s != "" {
   296				attrs = append(attrs, slog.String("component", s))
   297			}
   298		}
   299		if v := ctx.Value(agentKey); v != nil {
   300			if s, ok := v.(string); ok && s != "" {
   301				attrs = append(attrs, slog.String("agent", s))
   302			}
   303		}
   304	
   305		return attrs
   306	}

